/*
 * Portal Matemáticas · Academia Teseracto
 * v1.1 — sin cookies, cuentas, dependencias externas ni servicios de datos.
 * Documentado para continuar con despliegues incrementales.
 */
(()=>{'use strict';
const C=window.TESERACTO_CATALOG, P=window.TE_PRACTICE;
const APP=document.getElementById('app'), $=id=>document.getElementById(id);
if(!C||!P){APP.innerHTML='<div class="empty">No se han cargado los datos. Comprueba que has subido las carpetas «assets» y «data» junto al index.html.</div>';return}
const modules=C.modules, lookup=Object.fromEntries(modules.map(m=>[m.id,m]));
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const stageOf=g=>g.endsWith('P')?'primaria':g.endsWith('E')?'eso':'bach';
const course=g=>C.courses[g]||g, ell=(n,t)=>n>t?`${t}+`:n;
let storage={version:1,records:[],bookmarks:[],diagnostics:[],touched:[]};
try{const raw=JSON.parse(localStorage.getItem('teseracto-matematicas-v1')||'null');if(raw&&Array.isArray(raw.records))storage={...storage,...raw}}catch(e){}
const persist=()=>{try{localStorage.setItem('teseracto-matematicas-v1',JSON.stringify(storage))}catch(e){notify('No se ha podido guardar el avance en este navegador')}};
const now=()=>new Date().toISOString();
let ui={stage:'all',grade:'all',search:'',area:'all',quiz:null,diagnostic:null,diagGrade:'6P',viz:{a:1,h:0,k:-1,m:2,b:-2,x:2,y:3,n:3,d:4,dx:3,dy:2,angle:90}};
const dateDiff=(a,b)=>Math.abs(new Date(a)-new Date(b))/(24*3600000);
function progress(id){const rec=storage.records.filter(r=>r.id===id);const passed=rec.filter(r=>r.score>=4&&r.total===5);let consolidated=false;for(const r of passed)for(const s of passed){if(dateDiff(r.when,s.when)>=7&&(r.mode==='transfer'||s.mode==='transfer')){consolidated=true;break}}return {attempts:rec.length,consolidated,best:rec.length?Math.max(...rec.map(r=>r.score)):null,passed:passed.length}}
const explored=id=>storage.touched.includes(id);
const statusText=id=>{const p=progress(id);return p.consolidated?'Consolidado':p.attempts?'En revisión':explored(id)?'En aprendizaje':'Por empezar'};
function notify(s){const el=$('toast');el.textContent=s;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),3100)}
const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const groups=[['Fracciones',['recta-fracciones','fracciones-equivalentes','comparar-fracciones','sumar-restar-fracciones','multiplicar-fracciones','dividir-fracciones']],['Números y cálculo',['enteros-signos','potencias','jerarquia','radicales']],['Porcentajes y proporcionalidad',['porcentajes','proporcionalidad']],['Geometría y movimientos',['coordenadas','traslaciones','giros','reflexiones','simetria']],['Álgebra y ecuaciones',['distributiva','ecuaciones-1','polinomios','ecuaciones-2','intervalos']],['Funciones y gráficas',['rectas','pendiente-dos-puntos','dominio','parabolas','recorrido-parabola']]];
const groupOf=m=>groups.find(g=>g[1].includes(m.id))?.[0]||m.area;
const aliases={'recta-fracciones':'numerador denominador recta numérica fracción impropia números mixtos','fracciones-equivalentes':'simplificar amplificar reducir mcd','comparar-fracciones':'ordenar fracciones mayor menor denominador común','sumar-restar-fracciones':'sumas restas fracciones mcm denominador común','multiplicar-fracciones':'multiplicación fracciones producto','dividir-fracciones':'división fracciones cociente inversa','enteros-signos':'negativos positivos regla de signos','potencias':'exponentes cuadrados cubos raíces','proporcionalidad':'regla de tres directa proporciones','coordenadas':'ejes cartesianos abscisa ordenada puntos','giros':'rotación transportador ángulo','reflexiones':'espejo eje reflexión','simetria':'ejes simétrico espejo','rectas':'función lineal afín pendiente corte intersección','pendiente-dos-puntos':'ecuación recta pendiente dos puntos','parabolas':'función cuadrática segundo grado vértice eje simetría cortes raíces gráfica','recorrido-parabola':'rango imagen máximo mínimo vértice parábola','dominio':'racionales denominadores raíces restricciones valores de x','ecuaciones-2':'segundo grado fórmula discriminante factorizar','intervalos':'inecuaciones desigualdades intervalos abiertos cerrados','radicales':'raíz cuadrada radicando'};
const legacyPath='./temas/funciones/parabolas.html';
const legacyLink=()=>`<a class="btn" href="${legacyPath}">Abrir guía completa de parábolas V3 →</a>`;
const catalogHref=()=> '#/catalogo'+(ui.grade!=='all'?'?curso='+encodeURIComponent(ui.grade):ui.stage!=='all'?'?etapa='+encodeURIComponent(ui.stage):'');
function gradeLinks(stage){return `<div class="grade-links">${stage.grades.map(g=>`<a class="grade-link ${ui.grade===g?'selected':''}" href="#/catalogo?curso=${g}"><strong>${escapeHTML(course(g))}</strong><small>${modules.filter(m=>m.grades.includes(g)).length} temas</small></a>`).join('')}</div>${stage.id==='primaria'?'<p class="coming">1.º–4.º de Primaria: contenidos pendientes de incorporar.</p>':''}`}
function quickCourses(){return `<div class="course-chooser">${C.stages.map(s=>`<section><h3>${escapeHTML(s.label)}</h3>${gradeLinks(s)}</section>`).join('')}</div>`}
function legacyCard(){return `<article class="panel legacy-card"><p class="eyebrow">Guía ampliada · ESO y Bachillerato</p><h3>Parábolas, desde cero</h3><p>Guía original V3: 77 pasos guiados, 14 ejercicios y laboratorio gráfico. Complementa la lección breve del portal.</p>${legacyLink()}</article>`}
const icon=n=>n==='primaria'?'∑':n==='eso'?'ƒ':'π';
function smallTags(m){return `<span class="chip purple">${escapeHTML(m.area)}</span> ${m.grades.slice(0,3).map(g=>`<span class="chip">${escapeHTML(course(g))}</span>`).join('')} ${m.grades.length>3?`<span class="chip">+${m.grades.length-3} cursos</span>`:''}`}
function card(m){const p=progress(m.id);return `<article class="module-card"><div class="card-meta"><span class="chip ${p.consolidated?'green':''}">${statusText(m.id)}</span><span>· ${m.minutes} min</span></div><h3><a href="#/tema/${m.id}">${escapeHTML(m.title)}</a></h3><p>${escapeHTML(m.summary)}</p><div class="card-meta">${smallTags(m)}</div><div style="margin-top:16px"><a class="open-topic" href="#/tema/${m.id}">Entrar en la lección →</a></div></article>`}
function breadcrumbs(items){return `<div class="breadcrumbs"><a href="#/inicio">Inicio</a>${items.map(([s,h])=>`<span>›</span>${h?`<a href="${h}">${escapeHTML(s)}</a>`:`<strong>${escapeHTML(s)}</strong>`}`).join('')}</div>`}
function setNav(route){document.querySelectorAll('[data-nav],.mobile-nav a').forEach(x=>{let key=(x.getAttribute('data-nav')||x.getAttribute('href').split('/')[1]);x.classList.toggle('active',key===route||route==='tema'&&key==='catalogo'||route==='practica'&&key==='catalogo'||route==='diagnostico'&&key==='maer')})}
function heroGraph(){const pts=[];for(let x=-5;x<=5;x+=.11){let y=-.24*(x-1)**2+4;pts.push(`${210+x*24},${180-y*22}`)}return `<svg class="plot" viewBox="0 0 460 210" role="img" aria-label="Gráfica con parábola y puntos de referencia"><g stroke="#ffffff1d" stroke-width="1">${Array.from({length:11},(_,i)=>`<path d="M${100+i*24},10V199"/>`).join('')}${Array.from({length:9},(_,i)=>`<path d="M80,${15+i*22}H440"/>`).join('')}</g><g stroke="#ffffff60" stroke-width="2"><path d="M80,179H442 M210,9V199"/></g><polyline points="${pts.join(' ')}" stroke="#ffc66e" stroke-width="5" fill="none" stroke-linecap="round"/><circle cx="234" cy="92" r="7" fill="#fff" stroke="#ffc66e" stroke-width="3"/><g fill="#e4e6ff" font-size="14"><text x="242" y="83">Vértice</text><text x="417" y="195">x</text><text x="192" y="18">y</text></g></svg>`}
function home(){const total=modules.length, ex=modules.reduce((n,m)=>n+m.examples.length,0);return `<section class="hero"><div class="hero-text"><p class="eyebrow">Academia Teseracto · Matemáticas</p><h1>Las matemáticas se <strong>entienden</strong>. Paso a paso.</h1><p class="lede">De las fracciones de Primaria a las funciones de Bachillerato. Aprende con ejemplos claros, gráficos que puedes mover y ejercicios que explican cada resultado.</p><div class="btn-row"><a class="btn primary" href="#/catalogo">Explorar el temario <span>↗</span></a><a class="btn" href="#/maer">Encontrar mi ruta MAER</a></div><div class="stats"><div class="stat"><strong>${total}</strong><span>temas disponibles</span></div><div class="stat"><strong>${ex}</strong><span>ejemplos resueltos</span></div><div class="stat"><strong>3</strong><span>etapas educativas</span></div></div></div><div class="hero-visual"><div class="math-mark">DE LA PRIMERA DUDA A LA IDEA CLARA</div>${heroGraph()}<div class="math-tip"><strong>¿Por qué una parábola tiene un vértice?</strong> Primero lo ves, después lo construyes y, finalmente, lo resuelves tú.</div></div></section>
<section><div class="section-head"><div><p class="eyebrow">Un mismo conocimiento, distintas profundidades</p><h2>¿En qué curso estás?</h2><p>Elige tu curso y verás los temas disponibles, agrupados por bloques. Puedes cambiar de nivel cuando necesites repasar.</p></div></div><div class="card-grid">${C.stages.map((s,i)=>`<article class="stage-card"><div class="stage-icon">${icon(s.id)}</div><div class="grade-band">${s.id==='primaria'?'Fundamentos visuales':s.id==='eso'?'Conexiones y procedimientos':'Razonamiento y funciones'}</div><h3>${s.label}</h3><p>${s.id==='primaria'?'Fracciones, operaciones, coordenadas y geometría, con dibujos que ayudan a entender.':s.id==='eso'?'Álgebra, ecuaciones y funciones, sin perder de vista los conocimientos anteriores.':'Funciones y álgebra con la base necesaria para resolver con autonomía.'}</p>${gradeLinks(s)}<a href="#/catalogo?etapa=${s.id}">Ver todos los temas de ${s.label} →</a></article>`).join('')}</div></section>
<section class="home-search"><div class="section-head"><div><p class="eyebrow">Acceso directo</p><h2>¿Qué tema necesitas?</h2></div></div><form id="home-search-form" class="home-search-form"><label class="search-field"><span aria-hidden="true">⌕</span><input id="home-search" type="search" placeholder="Busca: fracciones, giros, ecuaciones…" aria-label="Buscar tema"></label><button class="btn primary" type="submit">Buscar</button></form><div class="quick-groups">${groups.map(([g])=>`<a class="btn small" href="#/catalogo?bloque=${encodeURIComponent(g)}">${escapeHTML(g)}</a>`).join('')}</div></section><section style="margin:55px 0 0"><div class="section-head"><div><p class="eyebrow">Cómo aprendemos</p><h2>El ciclo MAER, aplicado a las matemáticas</h2></div><a class="btn small" href="#/maer">Conocer el enfoque</a></div><div class="feature-strip"><div class="feature-card"><span class="tiny">M · MIRAR</span><p>Comprueba qué sabes con tareas breves.</p></div><div class="feature-card"><span class="tiny">A · ACLARAR</span><p>Identifica el paso que te está bloqueando.</p></div><div class="feature-card"><span class="tiny">E · ENTRENAR</span><p>Comprende, practica y aplica con pistas.</p></div><div class="feature-card"><span class="tiny">R · REVISAR</span><p>Retoma el tema y comprueba si se mantiene.</p></div></div></section>
<section style="margin-top:55px"><div class="section-head"><div><p class="eyebrow">Empieza por aquí</p><h2>Rutas de entrada</h2></div><a href="#/catalogo">Ver todos →</a></div><div class="card-grid">${['sumar-restar-fracciones','rectas','parabolas'].map(id=>card(lookup[id])).join('')}</div></section>`}
function catalog(){const params=new URLSearchParams(location.hash.split('?')[1]||'');const ss=params.get('etapa'),gg=params.get('curso'),qq=params.get('q'),bb=params.get('bloque');if(ss||gg||qq!==null||bb){ui.stage='all';ui.grade='all';ui.area='all';ui.search='';ui.group='all';if(ss&&C.stages.some(x=>x.id===ss))ui.stage=ss;if(gg&&C.courses[gg]){ui.grade=gg;ui.stage=stageOf(gg)}if(qq!==null)ui.search=qq;if(bb&&groups.some(x=>x[0]===bb))ui.group=bb}return `${breadcrumbs([['Temario']])}<p class="eyebrow">Encuentra tu próxima lección</p><h1>Elige tu curso o busca un tema.</h1><p class="lede">Los contenidos disponibles se organizan por curso y bloque. Puedes consultar cualquier nivel para reforzar las bases.</p><details class="course-picker" ${ui.grade==='all'&&ui.stage==='all'&&!ui.search&&(!ui.group||ui.group==='all')?'open':''}><summary>Elegir curso ${ui.grade!=='all'?'· '+escapeHTML(course(ui.grade)):''}</summary>${quickCourses()}</details><div class="catalog-toolbar"><label class="search-field" for="find-topic"><span aria-hidden="true">⌕</span><input id="find-topic" type="search" placeholder="Buscar: fracciones, parabolas, pendiente…" autocomplete="off" value="${escapeHTML(ui.search)}"></label><div class="filters" style="margin-top:12px"><label><span class="subtle">Etapa</span><select class="select" id="stage-filter"><option value="all">Todas</option>${C.stages.map(x=>`<option value="${x.id}" ${ui.stage===x.id?'selected':''}>${x.label}</option>`).join('')}</select></label><label><span class="subtle">Curso</span><select class="select" id="grade-filter"><option value="all">Todos los cursos</option>${Object.entries(C.courses).filter(([g])=>ui.stage==='all'||stageOf(g)===ui.stage).map(([g,n])=>`<option value="${g}" ${ui.grade===g?'selected':''}>${n}</option>`).join('')}</select></label><label><span class="subtle">Bloque temático</span><select class="select" id="group-filter"><option value="all">Todos los bloques</option>${groups.map(([g])=>`<option value="${escapeHTML(g)}" ${ui.group===g?'selected':''}>${escapeHTML(g)}</option>`).join('')}</select></label></div><div class="btn-row" style="margin-top:12px"><button class="btn small" data-action="reset-filters">Mostrar todos los temas</button><a class="btn small" href="#/maer">No sé por dónde empezar</a></div></div><div id="catalog-results" aria-live="polite"></div>`}
function updateCatalog(){const root=$('catalog-results');if(!root)return;const words=normalize(ui.search).trim().split(/\s+/).filter(Boolean);const matches=modules.filter(m=>(ui.stage==='all'||m.grades.some(g=>stageOf(g)===ui.stage))&&(ui.grade==='all'||m.grades.includes(ui.grade))&&(!ui.group||ui.group==='all'||groupOf(m)===ui.group)&&words.every(w=>normalize([m.title,m.summary,m.area,groupOf(m),aliases[m.id]||'',...m.grades.map(course)].join(' ')).includes(w)));const blocks=[...groups.map(g=>g[0]),...new Set(matches.map(groupOf).filter(g=>!groups.some(x=>x[0]===g)))];const selected=ui.grade!=='all'?course(ui.grade):ui.stage!=='all'?C.stages.find(s=>s.id===ui.stage).label:'Todos los cursos';root.innerHTML=`<div class="section-head" style="margin-top:0"><div><h2>${escapeHTML(selected)}</h2><p>${matches.length} temas disponibles · catálogo en ampliación</p></div></div>${matches.length?blocks.map(g=>{const ms=matches.filter(m=>groupOf(m)===g);return ms.length?`<section class="catalog-block"><h3>${escapeHTML(g)} <span class="block-count">${ms.length}</span></h3><div class="module-grid">${ms.map(card).join('')}${ms.some(m=>m.id==='parabolas')?legacyCard():''}</div></section>`:''}).join(''):`<div class="empty"><h3>No encontramos ese tema en los filtros seleccionados.</h3><p>Prueba con otra palabra o busca en todos los cursos. Si no aparece, todavía no se ha incorporado.</p><button class="btn primary" data-action="expand-search">Buscar en todos los cursos</button></div>`}`}
function docLinks(){return '<a href="./materiales/01_Cuaderno_Fracciones_Alumno.pdf" target="_blank" rel="noopener">Cuaderno de 90 minutos (PDF)</a> · <a href="./materiales/02_Solucionario_Fracciones_Docente.pdf" target="_blank" rel="noopener">Solucionario (PDF)</a> · <a href="./materiales/03_Guia_MAER_3_Clases_Fracciones.pdf" target="_blank" rel="noopener">Guía docente de 3 sesiones (PDF)</a>'}
function status(id){const p=progress(id);return `<span class="chip ${p.consolidated?'green':p.attempts?'orange':''}">${statusText(id)}</span>`}
function visualControls(type){const v=ui.viz;
 const range=(key,label,min,max,step=1)=>`<label>${label}: <strong class="v-val" data-value="${key}">${v[key]}</strong><input data-vkey="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${v[key]}" aria-label="${label}"></label>`;
 if(type==='fraction-line')return range('n','Numerador',0,12)+range('d','Denominador',2,10);
 if(type==='fractions'||type==='fraction-ops')return range('n','Partes coloreadas',1,9)+range('d','Partes por unidad',2,10);
 if(type==='coordinates')return range('x','Coordenada x',-5,5)+range('y','Coordenada y',-5,5);
 if(type==='transforms')return range('dx','Movimiento horizontal',-4,4)+range('dy','Movimiento vertical',-4,4);
 if(type==='parabola')return range('a','Apertura a',-3,3)+range('h','Desplazamiento h',-4,4)+range('k','Altura k',-5,5);
 if(type==='line-graph')return range('m','Pendiente m',-4,4)+range('b','Corte b',-6,6);
 if(type==='number-line'||type==='domain-graph')return range('x','Punto x',-6,6);
 return ''
}
function plotBase(size='large'){let lines='',labels='';const left=56,right=655,top=22,bottom=328,xscale=(right-left)/14,yscale=(bottom-top)/14,X=x=>left+(x+7)*xscale,Y=y=>bottom-(y+7)*yscale;for(let i=-7;i<=7;i++){const px=X(i),py=Y(i);lines+=`<path d="M${px},${top}V${bottom} M${left},${py}H${right}" stroke="${i===0?'#9fabc9':'#e5eaf5'}" stroke-width="${i===0?1.8:1}"/>`;if(i%2===0&&i!==0)labels+=`<text x="${px}" y="${Y(0)+18}" text-anchor="middle" font-size="12" fill="#8290a7">${i}</text><text x="${X(0)-10}" y="${py+5}" text-anchor="end" font-size="12" fill="#8290a7">${i}</text>`}return {lines,labels,X,Y,left,right,top,bottom}}
function makePlot(fn,points=[],options={}){const f=plotBase(),p=[];for(let x=-7;x<=7;x+=.035){const y=fn(x);if(Number.isFinite(y)&&y>=-20&&y<=20)p.push(`${f.X(x).toFixed(1)},${f.Y(y).toFixed(1)}`)}const dots=points.map(([x,y,label])=>`<circle cx="${f.X(x)}" cy="${f.Y(y)}" r="6" fill="#f59e0b" stroke="#fff" stroke-width="2"/><text x="${f.X(x)+10}" y="${f.Y(y)-10}" font-size="15" font-weight="700" fill="#172554">${escapeHTML(label||`(${x},${y})`)}</text>`).join('');return `<svg class="visual-graphic" viewBox="0 0 700 360" role="img" aria-label="${escapeHTML(options.label||'Gráfica cartesiana manipulable')}"><defs><clipPath id="plotclip"><rect x="${f.left}" y="${f.top}" width="${f.right-f.left}" height="${f.bottom-f.top}"/></clipPath></defs>${f.lines}${f.labels}<g clip-path="url(#plotclip)"><polyline points="${p.join(' ')}" fill="none" stroke="#5e55d8" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${dots}</g><text x="${f.right+8}" y="${f.Y(0)+5}" fill="#34415b">x</text><text x="${f.X(0)+8}" y="${f.top+2}" fill="#34415b">y</text></svg>`}
function renderVisual(type){const v=ui.viz;let svg='',caption='';const fraction=(num,den,y,color='#5e55d8',label='')=>{const d=Math.max(1,den),n=Math.max(0,num);let rows='',w=500/d;for(let i=0;i<d;i++)rows+=`<rect x="${100+i*w}" y="${y}" width="${w-2}" height="48" rx="3" fill="${i<n?color:'#edf1f9'}" stroke="#b8c3d5"/>`;return `<text x="100" y="${y-10}" font-size="16" fill="#172554" font-weight="700">${label||`${n}/${d}`}</text>`+rows};
if(type==='fraction-line'){
 const d=Math.max(2,v.d),n=Math.min(v.n,2*d),xx=a=>70+a*265;let ticks='',labels='';for(let i=0;i<=2*d;i++){const x=xx(i/d);ticks+=`<path d="M${x},152V180" stroke="#c1c9da" stroke-width="${i%d===0?3:1.5}"/>`;if(i%d===0)labels+=`<text x="${x}" y="208" text-anchor="middle" font-size="21" fill="#172554">${i/d}</text>`}const end=xx(n/d);svg=`<svg class="visual-graphic" viewBox="0 0 700 310" role="img" aria-label="Fracción en recta numérica de cero a dos"><path d="M70,165H610" stroke="#172554" stroke-width="3"/>${ticks}${labels}<path d="M70,165H${end}" stroke="#5e55d8" stroke-width="8" stroke-linecap="round"/><circle cx="${end}" cy="165" r="11" fill="#f59e0b" stroke="#fff" stroke-width="3"/><text x="${end}" y="130" text-anchor="middle" font-size="22" fill="#172554" font-weight="850">${n}/${d}</text></svg>`;caption=`${n}/${d} = ${P.fstr(n,d)}: has avanzado ${n} intervalos de tamaño 1/${d}.`}
else if(type==='fractions'||type==='fraction-ops'){const d=Math.max(2,v.d),n=Math.min(v.n,d),double=d*2;svg=`<svg class="visual-graphic" viewBox="0 0 700 260" role="img" aria-label="Dos barras muestran fracciones equivalentes">${fraction(n,d,67,'#5e55d8',`${n}/${d}`)}${fraction(n*2,double,157,'#0c899c',`${n*2}/${double}`)}</svg>`;caption=`Las dos barras representan ${P.fstr(n,d)} de la misma unidad: ${n}/${d} = ${n*2}/${double}.`}
else if(type==='coordinates'){const f=plotBase(),X=f.X,Y=f.Y;svg=`<svg class="visual-graphic" viewBox="0 0 700 360" role="img" aria-label="Plano cartesiano con punto móvil">${f.lines}${f.labels}<path d="M${X(v.x)},${Y(0)}V${Y(v.y)}H${X(0)}" fill="none" stroke="#f59e0b" stroke-width="3" stroke-dasharray="7 7"/><circle cx="${X(v.x)}" cy="${Y(v.y)}" r="8" fill="#5e55d8" stroke="white" stroke-width="3"/><text x="${X(v.x)+11}" y="${Y(v.y)-12}" font-size="21" fill="#172554" font-weight="800">P(${v.x},${v.y})</text></svg>`;caption=`Primero x=${v.x} (${v.x<0?'izquierda':v.x>0?'derecha':'sin desplazamiento'}); después y=${v.y} (${v.y<0?'abajo':v.y>0?'arriba':'sin desplazamiento'}).`}
else if(type==='transforms'){const f=plotBase(),old=[[0,0],[1,3],[3,0]],moved=old.map(([x,y])=>[x+v.dx,y+v.dy]);let shape=(arr,color)=>`<polygon points="${arr.map(([x,y])=>`${f.X(x)},${f.Y(y)}`).join(' ')}" fill="${color}22" stroke="${color}" stroke-width="4" stroke-linejoin="round"/>`;svg=`<svg class="visual-graphic" viewBox="0 0 700 360" role="img" aria-label="Triángulo original y su imagen trasladada">${f.lines}${shape(old,'#5e55d8')}${shape(moved,'#0c899c')}${old.map((p,i)=>`<path d="M${f.X(p[0])},${f.Y(p[1])}L${f.X(moved[i][0])},${f.Y(moved[i][1])}" stroke="#f59e0b" stroke-dasharray="6 6" stroke-width="2"/>`).join('')}</svg>`;caption=`Cada vértice pasa a (x+${v.dx}, y+${v.dy}). Las flechas naranjas muestran el mismo desplazamiento.`}
else if(type==='parabola'){let a=v.a||1;svg=makePlot(x=>a*(x-v.h)**2+v.k,[[v.h,v.k,'Vértice']],{label:'Parábola con vértice y ejes'});caption=`y = ${a}(x − (${v.h}))² + (${v.k}); vértice (${v.h},${v.k}); dominio ℝ; recorrido ${a>0?`[${v.k}, +∞)`:`(−∞, ${v.k}]`}.`}
else if(type==='line-graph'){svg=makePlot(x=>v.m*x+v.b,[[0,v.b,'Corte Y']],{label:'Recta con pendiente y corte modificables'});caption=`y = ${v.m}x + (${v.b}); m=${v.m} (${v.m>0?'creciente':v.m<0?'decreciente':'horizontal'}); corte Y: (0,${v.b}).`}
else if(type==='number-line'||type==='domain-graph'){const x=v.x,pos=z=>350+z*39;let ticks='';for(let i=-7;i<=7;i++)ticks+=`<line x1="${pos(i)}" y1="132" x2="${pos(i)}" y2="156" stroke="#9dadc4"/><text x="${pos(i)}" y="182" text-anchor="middle" font-size="15" fill="#62728c">${i}</text>`;svg=`<svg class="visual-graphic" viewBox="0 0 700 270" role="img" aria-label="Recta numérica con punto desplazable"><path d="M55,145H645" stroke="#172554" stroke-width="3"/>${ticks}<circle cx="${pos(x)}" cy="145" r="11" fill="#5e55d8" stroke="white" stroke-width="3"/><text x="${pos(x)}" y="117" text-anchor="middle" fill="#172554" font-size="23" font-weight="800">${x}</text></svg>`;caption=type==='domain-graph'?`El punto x=${x} ayuda a comprobar qué valores se permiten. Para 1/(x−${x}), ese mismo valor queda excluido.`:`Los números positivos están a la derecha de 0; los negativos a la izquierda.`}
else if(type==='balance'){svg=`<svg class="visual-graphic" viewBox="0 0 700 270" role="img" aria-label="Balanza que representa una ecuación"><path d="M350 80V210 M270 210H430 M180 80H520" stroke="#172554" stroke-width="8" stroke-linecap="round"/><path d="M210 80L165 185H255Z M490 80L445 185H535Z" fill="#eef0ff" stroke="#5e55d8" stroke-width="4"/><circle cx="350" cy="80" r="13" fill="#f59e0b"/><text x="210" y="167" text-anchor="middle" fill="#172554" font-size="26" font-weight="800">3x</text><text x="490" y="167" text-anchor="middle" fill="#172554" font-size="26" font-weight="800">15</text></svg>`;caption='Una ecuación conserva la igualdad: si 3x=15, divide ambos miembros entre 3 y obtienes x=5.'}
else if(type==='percent'||type==='bars'){const total=10*10,cells=Array.from({length:total},(_,i)=>`<rect x="${95+(i%10)*40}" y="${32+Math.floor(i/10)*22}" width="35" height="18" rx="3" fill="${i<25?'#5e55d8':'#e8eafa'}" stroke="#fff"/>`).join('');svg=`<svg class="visual-graphic" viewBox="0 0 700 300" role="img" aria-label="Cuadrícula de cien partes con veinticinco coloreadas">${cells}</svg>`;caption='25 de 100 casillas = 25 % = 1/4. Lo mismo se puede ver en una fracción o en decimal: 0,25.'}
else if(type==='squares'){svg=makePlot(x=>x*x/4,[[0,0,'(0,0)'],[4,4,'(4,4)']],{label:'Curva de cuadrados'});caption='Al aumentar |x|, su cuadrado aumenta. Por ejemplo, (−4)²=16 y 4²=16.'}
else{svg=makePlot(x=>x,[[0,0,'0']],{label:'Ejes numéricos'});caption='El razonamiento matemático se fortalece al dibujar los pasos, no solo el resultado.'}
return {svg,caption}}
function visual(m){const t=m.visual,res=renderVisual(t);return `<div class="visual-shell"><div id="svgwrap">${res.svg}</div><p class="visual-caption" id="vcap">${escapeHTML(res.caption)}</p>${visualControls(t)?`<div class="visual-toolbar no-print">${visualControls(t)}</div>`:''}</div>`}
function related(m){const direct=m.strong.map(id=>lookup[id]).filter(Boolean);const later=modules.filter(x=>x.strong.includes(m.id)).slice(0,5);return `<aside class="lesson-sidebar"><div class="sidebar-box"><h3>Tu ruta hacia este tema</h3>${direct.length?`<p>Estos conocimientos te ayudan a entender la lección:</p><div class="dependency-list">${direct.map(x=>`<a class="dependency-link" href="#/tema/${x.id}">${escapeHTML(x.title)} →</a>`).join('')}</div>`:'<p>Puedes empezar aquí sin otros módulos de la biblioteca.</p>'}${later.length?`<h3 style="margin-top:16px">Después podrás…</h3><div class="dependency-list">${later.map(x=>`<a class="dependency-link" href="#/tema/${x.id}">${escapeHTML(x.title)} →</a>`).join('')}</div>`:''}</div><div class="sidebar-box"><h3>Enfoque MAER</h3><p>No necesitas aprenderlo todo de golpe. Primero comprende un paso, luego practica y finalmente comprueba si puedes hacerlo solo.</p><a href="#/maer">¿Cómo funciona?</a></div></aside>`}
function topic(id){const m=lookup[id];if(!m)return notFound();if(!storage.touched.includes(id)){storage.touched.push(id);persist()}return `${breadcrumbs([['Temario',catalogHref()],[m.title]])}<header class="topic-head"><div><p class="eyebrow">${escapeHTML(m.area)} · ${m.minutes} min de lectura y práctica</p><h1>${escapeHTML(m.title)}</h1><p>${escapeHTML(m.summary)}</p><div class="card-meta">${smallTags(m)} ${status(m.id)}</div></div><div class="btn-row"><button class="btn small" data-action="bookmark" data-id="${id}">${storage.bookmarks.includes(id)?'★ Quitar de guardados':'☆ Guardar tema'}</button><button class="btn small" data-action="print">Imprimir explicación</button></div></header>${id==='parabolas'?`<section class="panel legacy-banner"><div><h2>¿Quieres estudiarlo con más detalle?</h2><p>La guía original V3 desarrolla 77 pasos, 14 ejercicios y un laboratorio gráfico.</p></div>${legacyLink()}</section>`:''}${groupOf(m)==='Fracciones'?'<section class="panel legacy-banner"><div><h2>Practica también en papel</h2><p>Cuaderno MAER de fracciones, listo para imprimir.</p></div><a class="btn" href="./materiales/01_Cuaderno_Fracciones_Alumno.pdf" target="_blank" rel="noopener">Abrir cuaderno PDF →</a></section>':''}<div class="learning-layout"><div class="lesson-body"><section class="lesson-section"><div class="panel"><span class="section-n">01 · CONSTRUIR SENTIDO</span><h2>Primero, entiende la idea</h2><p>${escapeHTML(m.summary)}</p><p><strong>¿Para qué te servirá?</strong> ${escapeHTML(m.why)}</p>${visual(m)}</div></section><section class="lesson-section"><div class="panel"><span class="section-n">02 · MODELO GUIADO</span><h2>Cómo se hace, paso a paso</h2><ol class="step-list">${m.steps.map(x=>`<li><span>${escapeHTML(x)}</span></li>`).join('')}</ol></div></section><section class="lesson-section"><div class="panel"><span class="section-n">03 · LO HAGO YO</span><h2>Ejemplos completamente resueltos</h2>${m.examples.map((ex,i)=>`<div class="worked"><p class="question">Ejemplo ${i+1}. ${escapeHTML(ex.q)}</p><p class="working">${escapeHTML(ex.work)}</p><p class="answer">Resultado: ${escapeHTML(ex.answer)}</p></div>`).join('')}<div class="note"><strong>Un error que conviene evitar:</strong> ${escapeHTML(m.trap)}</div><p class="subtle"><strong>Truco de comprobación:</strong> ${escapeHTML(m.tip)}</p></div></section><section class="lesson-section" id="entrenar"><div class="panel"><span class="section-n">04 · ENTRENAR</span><h2>Ahora practicas tú</h2><p>Las preguntas se generan con números diferentes. Después de responder, verás los pasos de la solución, no solo un «bien» o «mal».</p><div class="practice-choice"><button class="choice" data-action="start-quiz" data-id="${id}" data-mode="guided"><strong>01 · Con apoyo</strong><span>5 ejercicios con corrección y procedimiento.</span><b>Empezar →</b></button><button class="choice" data-action="start-quiz" data-id="${id}" data-mode="independent"><strong>02 · Yo solo</strong><span>5 problemas nuevos para comprobar lo aprendido.</span><b>Empezar →</b></button><button class="choice" data-action="start-quiz" data-id="${id}" data-mode="transfer"><strong>03 · Aplicar</strong><span>5 variantes, incluidas situaciones contextualizadas cuando corresponda.</span><b>Empezar →</b></button></div><p class="subtle" style="margin-top:16px">Para considerar un tema consolidado: al menos 4 aciertos de 5 en dos días separados por una semana, y una comprobación de aplicación. Una sola tanda correcta no basta.</p></div></section></div>${related(m)}</div>`}
function quizStart(id,mode){if(!lookup[id]||!['guided','independent','transfer'].includes(mode))return;const seed=Math.floor(Date.now()/1000)+Math.floor(Math.random()*1e6);ui.quiz={id,mode,items:Array.from({length:5},(_,i)=>P.generate(id,seed+i*41,mode)),index:0,results:[],checked:false,answer:'',saved:false};location.hash=`#/practica/${id}/${mode}`;render()}
function quiz(){const s=ui.quiz;if(!s)return `<div class="panel"><h2>No hay una tanda activa</h2><p>Entra en un tema y elige practicar.</p><a class="btn primary" href="#/catalogo">Elegir tema</a></div>`;const m=lookup[s.id];if(s.index>=s.items.length)return quizEnd();const ex=s.items[s.index],pct=s.index/s.items.length*100;const modeLabel=s.mode==='guided'?'Con apoyo':s.mode==='independent'?'Yo solo':'Aplicar';return `${breadcrumbs([['Temario','#/catalogo'],[m.title,`#/tema/${m.id}`],['Práctica']])}<div class="quiz-wrap"><div class="card-meta"><span class="chip purple">${escapeHTML(modeLabel)}</span><span>${s.index+1} de ${s.items.length} ejercicios</span></div><div class="progress-indicator" role="progressbar" aria-label="Avance de la tanda" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${s.index}"><span style="width:${pct}%"></span></div><section class="quiz-card"><p class="eyebrow">${escapeHTML(m.title)}</p><h2>${escapeHTML(ex.prompt)}</h2><label for="quiz-answer"><strong>Tu respuesta</strong><p class="subtle">Para fracciones puedes escribir 3/4; también se aceptan fracciones equivalentes y decimales.</p></label><input id="quiz-answer" class="answer-field" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" placeholder="Escribe aquí tu respuesta" value="${escapeHTML(s.answer)}" ${s.checked?'disabled':''} aria-describedby="quiz-help"><p id="quiz-help" class="subtle">${s.checked?'Comprueba la explicación y pasa al siguiente.':'Piensa el resultado antes de comprobar.'}</p>${!s.checked?`<div class="btn-row"><button class="btn primary" data-action="quiz-check">Comprobar respuesta</button><button class="btn light" data-action="quiz-hint">Ver una pista</button></div><p id="quiz-hint" class="subtle" style="display:none">${escapeHTML(ex.hint)}</p>`:`<div class="feedback ${s.results.at(-1)?'good':'bad'}"><strong>${s.results.at(-1)?'Respuesta correcta.':'Esta vez no ha salido; revisa cómo se hace.'}</strong><p><strong>Solución: ${escapeHTML(ex.answer)}</strong></p><p class="work">${escapeHTML(ex.work)}</p></div><div class="btn-row"><button class="btn primary" data-action="quiz-next">${s.index===4?'Terminar tanda':'Siguiente ejercicio →'}</button></div>`}</section><p class="subtle" style="margin-top:16px;text-align:center">El avance se guarda en tu navegador, no en un servidor. <a href="#/tema/${s.id}">Volver al tema</a></p></div>`}
function quizEnd(){const s=ui.quiz,m=lookup[s.id],score=s.results.filter(Boolean).length;return `${breadcrumbs([['Temario','#/catalogo'],[m.title,`#/tema/${m.id}`],['Resultado']])}<section class="panel quiz-wrap quiz-finish"><p class="eyebrow">REVISAR · FIN DE LA TANDA</p><div class="score">${score} / 5</div><h2>${score>=4?'Buen resultado: sigue revisándolo en el tiempo.':'Has localizado qué merece la pena practicar de nuevo.'}</h2><p>${score>=4?'Conseguir 4 de 5 hoy es una buena evidencia, pero no demuestra por sí solo consolidación. Regresa otro día y realiza también una tanda de aplicación.':'Vuelve a los ejemplos y a la pista del tema. Repetir con números nuevos permite averiguar qué paso se está resistiendo.'}</p><div class="btn-row" style="justify-content:center"><button class="btn primary" data-action="start-quiz" data-id="${s.id}" data-mode="${s.mode}">Nueva tanda</button><a class="btn" href="#/tema/${s.id}">Repasar explicación</a><a class="btn" href="#/progreso">Mi progreso</a></div><p class="subtle">Estado de este tema: <strong>${statusText(s.id)}</strong>.</p></section>`}
function markQuizFinished(){const s=ui.quiz;if(!s||s.saved||s.results.length!==5)return;storage.records.push({id:s.id,mode:s.mode,score:s.results.filter(Boolean).length,total:5,when:now()});s.saved=true;persist()}
function maer(){return `${breadcrumbs([['Ruta MAER']])}<p class="eyebrow">Método Algorítmico de Enseñanza Recursiva</p><h1>No necesitas repetir todo. Necesitas encontrar el paso que falta.</h1><p class="lede">MAER significa también <strong>Mirar · Aclarar · Entrenar · Revisar</strong>. En el portal, este ciclo funciona como guía de estudio. El análisis pedagógico completo requiere observar el procedimiento del estudiante, no solamente un test.</p><div class="maer-cycle"><div class="cycle-card"><div class="letter">M</div><h3>Mirar</h3><p>Empieza con una comprobación breve y sin nota escolar.</p></div><div class="cycle-card"><div class="letter">A</div><h3>Aclarar</h3><p>Busca el prerrequisito que explica los errores.</p></div><div class="cycle-card"><div class="letter">E</div><h3>Entrenar</h3><p>Modelo → práctica guiada → autonomía → aplicación.</p></div><div class="cycle-card"><div class="letter">R</div><h3>Revisar</h3><p>Vuelve una semana después y comprueba si perdura.</p></div></div><div class="two-col"><section class="panel"><p class="eyebrow">Una exploración inicial</p><h2>¿Por dónde empiezo?</h2><p>Selecciona tu curso para probar doce preguntas cortas sobre contenidos y prerrequisitos. Al terminar recibirás una <strong>ruta orientativa</strong>, no una calificación ni un diagnóstico.</p><label for="diag-grade"><strong>Curso</strong></label><div class="btn-row"><select class="select" id="diag-grade">${Object.entries(C.courses).map(([g,label])=>`<option value="${g}" ${ui.diagGrade===g?'selected':''}>${label}</option>`).join('')}</select><button class="btn primary" data-action="start-diagnostic">Empezar exploración</button></div><p class="subtle">Duración aproximada: 15–20 minutos. Sin nombre, correo ni cuenta.</p></section><section class="panel"><p class="eyebrow">Un ejemplo real de aprendizaje</p><h2>«No me salen las ecuaciones»</h2><div class="route-step"><span class="step-dot">1</span><div><h3>Mirar</h3><p>El estudiante reconoce 3x=12, pero se detiene ante una ecuación con fracciones.</p></div></div><div class="route-step"><span class="step-dot">2</span><div><h3>Aclarar</h3><p>La dificultad puede estar en los denominadores, no en la idea de ecuación.</p></div></div><div class="route-step"><span class="step-dot">3</span><div><h3>Entrenar y volver</h3><p>Trabaja equivalencias y sumas, sin abandonar el objetivo original: resolver ecuaciones.</p></div></div><div class="route-step"><span class="step-dot">4</span><div><h3>Revisar</h3><p>Comprueba que lo aplica por su cuenta otro día y con enunciados distintos.</p></div></div></section></div><div class="panel" style="margin-top:20px"><h2>Lo que este portal sí y no hace</h2><p>Puede ofrecer explicaciones, prácticas autocorregibles y rutas orientativas a partir de respuestas. <strong>No diagnostica trastornos, no sustituye la valoración docente y no interpreta conductas psicológicas.</strong> Para la aplicación íntegra del método en la academia se necesita observar los pasos escritos y acordar objetivos con la familia.</p><p class="subtle">La especificación de la capa operativa MAER facilitada para este proyecto es una propuesta v0.1 aún pendiente de aprobación canónica. Sus criterios se usan aquí como orientación pedagógica, no se presentan como normativa definitiva.</p></div>`}
const diagPools={
 '5P':['recta-fracciones','fracciones-equivalentes','comparar-fracciones','sumar-restar-fracciones','multiplicar-fracciones','potencias'],
 '6P':['fracciones-equivalentes','sumar-restar-fracciones','dividir-fracciones','potencias','coordenadas','traslaciones'],
 '1E':['enteros-signos','jerarquia','fracciones-equivalentes','ecuaciones-1','distributiva','coordenadas'],
 '2E':['enteros-signos','sumar-restar-fracciones','distributiva','ecuaciones-1','polinomios','rectas'],
 '3E':['ecuaciones-1','polinomios','rectas','pendiente-dos-puntos','dominio','parabolas'],
 '4E':['ecuaciones-1','polinomios','rectas','dominio','ecuaciones-2','parabolas'],
 '1B':['polinomios','rectas','pendiente-dos-puntos','dominio','parabolas','ecuaciones-2'],
 '2B':['ecuaciones-2','dominio','intervalos','parabolas','recorrido-parabola','pendiente-dos-puntos']};
function diagnosticStart(){const grade=ui.diagGrade,ids=diagPools[grade]||diagPools['6P'];const seed=Math.floor(Date.now()/1000);const items=ids.flatMap((id,j)=>[P.generate(id,seed+j*99,'guided'),P.generate(id,seed+j*99+101,'transfer')].map(ex=>({...ex,id})));ui.diagnostic={grade,items,index:0,answers:[],finished:false};location.hash='#/diagnostico';render()}
function diagnostic(){const s=ui.diagnostic;if(!s)return `${breadcrumbs([['Ruta MAER','#/maer'],['Exploración']])}<div class="empty">No hay una exploración iniciada. <a href="#/maer">Volver a MAER</a></div>`;if(s.index>=s.items.length)return diagnosticEnd();const ex=s.items[s.index];return `${breadcrumbs([['Ruta MAER','#/maer'],['Exploración inicial']])}<div class="quiz-wrap"><p class="eyebrow">MIRAR · ${course(s.grade)}</p><h1>Exploración de fundamentos</h1><div class="card-meta"><span class="chip purple">${s.index+1} de ${s.items.length}</span><span>${escapeHTML(lookup[ex.id].title)}</span></div><div class="progress-indicator" role="progressbar" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${s.index}" aria-label="Progreso"><span style="width:${s.index/12*100}%"></span></div><section class="quiz-card"><h2>${escapeHTML(ex.prompt)}</h2><label for="diag-answer">Tu respuesta</label><input id="diag-answer" class="answer-field" type="text" inputmode="decimal" placeholder="Escribe tu respuesta" autocomplete="off"><p class="subtle">Si no lo sabes, puedes pasar sin responder; eso también ayuda a elegir qué revisar.</p><div class="btn-row"><button class="btn primary" data-action="diag-next">${s.index===11?'Ver mi ruta':'Continuar →'}</button></div></section></div>`}
function diagnosticEnd(){const s=ui.diagnostic,grade=s.grade,ids=diagPools[grade];let total=0;const per=ids.map(id=>{const a=s.answers.filter(x=>x.id===id);const right=a.filter(x=>x.right).length;total+=right;return {id,right,count:a.length}});const priority=per.filter(x=>x.right<2).map(x=>x.id);const prereq=[...new Set(priority.flatMap(id=>lookup[id]?.strong||[]))].filter(id=>lookup[id]);const recommended=[...prereq,...priority].filter((id,i,arr)=>arr.indexOf(id)===i).slice(0,7);return `${breadcrumbs([['Ruta MAER','#/maer'],['Resultado orientativo']])}<p class="eyebrow">ACLARAR · RUTA SUGERIDA</p><h1>Tu siguiente paso está más claro.</h1><p class="lede">Esta exploración no determina un nivel escolar ni sustituye una prueba diagnóstica MAER con observación de procedimientos. Sirve para elegir un primer recorrido de estudio.</p><div class="summary-grid"><div class="summary-tile"><strong>${s.items.length}</strong><span>preguntas exploradas</span></div><div class="summary-tile"><strong>${priority.length}</strong><span>temas que conviene revisar</span></div><div class="summary-tile"><strong>${recommended.length}</strong><span>paradas sugeridas</span></div></div><div class="two-col"><section class="panel"><h2>Observaciones por tema</h2>${per.map(x=>`<div class="progress-item"><div><h3>${escapeHTML(lookup[x.id].title)}</h3><p>${x.right===2?'Resuelto en estas dos preguntas':x.right===1?'Conviene probar más ejemplos':'Conviene trabajar el fundamento'}</p></div><span class="chip ${x.right===2?'green':x.right===0?'orange':''}">${x.right}/2</span></div>`).join('')}</section><section class="panel"><h2>Ruta para entrenar</h2>${recommended.length?recommended.map((id,i)=>`<div class="route-step"><span class="step-dot">${i+1}</span><div><h3>${escapeHTML(lookup[id].title)}</h3><p>${prereq.includes(id)?'Base que conviene revisar primero':'Contenido de la exploración para reforzar'}</p><a href="#/tema/${id}">Abrir lección →</a></div></div>`).join(''):'<p>Las respuestas han salido bien en esta exploración. Elige un contenido nuevo y pruébalo de forma autónoma y en aplicación.</p>'}<div class="btn-row"><a class="btn primary" href="#/catalogo?curso=${grade}">Temario de mi curso</a><a class="btn" href="#/maer">Otra exploración</a></div></section></div><p class="subtle" style="margin-top:20px">En este resultado no se muestran etiquetas clínicas ni se infieren características personales. El profesor puede valorar los procedimientos escritos por separado.</p>`}
function summary(){const practiced=new Set(storage.records.map(r=>r.id)).size,consolidated=modules.filter(m=>progress(m.id).consolidated).length;return `${breadcrumbs([['Mi progreso']])}<p class="eyebrow">Tu espacio de estudio · sin cuentas</p><h1>Un avance pequeño también es avance.</h1><p class="lede">Aquí se registran las prácticas de este navegador. Un tema no se da por consolidado tras un único intento: hay que poder resolverlo en distintos días y aplicarlo.</p><div class="summary-grid"><div class="summary-tile"><strong>${storage.touched.length}</strong><span>lecciones exploradas</span></div><div class="summary-tile"><strong>${practiced}</strong><span>temas practicados</span></div><div class="summary-tile"><strong>${consolidated}</strong><span>temas con revisión espaciada</span></div></div><div class="panel"><div class="section-head" style="margin-top:0"><div><h2>Tu biblioteca personal</h2><p>Temas guardados o iniciados</p></div></div>${[...new Set([...storage.bookmarks,...storage.touched,...storage.records.map(r=>r.id)])].filter(id=>lookup[id]).length?[...new Set([...storage.bookmarks,...storage.touched,...storage.records.map(r=>r.id)])].filter(id=>lookup[id]).map(id=>{const m=lookup[id],p=progress(id);return `<div class="progress-item"><div><h3><a href="#/tema/${id}">${escapeHTML(m.title)}</a></h3><p>${p.attempts} tandas · mejor resultado ${p.best===null?'sin prácticas':`${p.best}/5`} · ${statusText(id)}</p></div><div class="actions"><span class="chip ${p.consolidated?'green':''}">${p.consolidated?'Consolidado':p.attempts?'En revisión':'Explorado'}</span><a class="btn small" href="#/tema/${id}">Abrir</a></div></div>`}).join(''):'<div class="empty">Todavía no has explorado temas. <a href="#/catalogo">Visita el temario</a> para empezar.</div>'}</div><div class="panel" style="margin-top:20px"><h2>Tu progreso es tuyo</h2><p>Los datos se almacenan exclusivamente en este navegador, mediante almacenamiento local. No se envían a Teseracto ni se comparten entre dispositivos automáticamente. Guarda una copia JSON y podrás importarla en otro móvil u ordenador.</p><div class="btn-row"><button class="btn primary" data-action="export-json">Exportar progreso JSON</button><button class="btn" data-action="import-json">Importar JSON</button><button class="btn light" data-action="clear-progress">Borrar este progreso</button></div><p class="subtle">No incluyas nombres completos, informes clínicos ni información personal de menores en el archivo exportado.</p></div>`}
function docentes(){return `${breadcrumbs([['Docentes']])}<p class="eyebrow">Material de apoyo · uso educativo</p><h1>El aula y el portal se complementan.</h1><p class="lede">El portal explica y entrena; la observación del procedimiento, la devolución a la familia y la decisión de intervención siguen siendo responsabilidad del docente.</p><div class="card-grid"><article class="panel"><p class="eyebrow">Material imprimible</p><h2>Cuaderno: fracciones</h2><p>Secuencia original de 90 minutos sobre recta, equivalencias, comparación y operaciones. Espacio para demostrar el procedimiento.</p><a class="btn primary" href="./materiales/01_Cuaderno_Fracciones_Alumno.pdf" target="_blank">Abrir cuaderno PDF</a></article><article class="panel"><p class="eyebrow">Corrección razonada</p><h2>Solucionario docente</h2><p>Respuestas con pasos, errores habituales y criterios de corrección, no solo números finales.</p><a class="btn primary" href="./materiales/02_Solucionario_Fracciones_Docente.pdf" target="_blank">Abrir solucionario</a></article><article class="panel"><p class="eyebrow">Plan de enseñanza</p><h2>Guía de tres clases</h2><p>Tres sesiones de 60 minutos, con modelado, práctica y regresos al objetivo original.</p><a class="btn primary" href="./materiales/03_Guia_MAER_3_Clases_Fracciones.pdf" target="_blank">Abrir guía docente</a></article></div><section class="panel" style="margin-top:22px"><h2>Recomendaciones MAER para acompañar el trabajo</h2><div class="two-col"><div><h3>Mirar y aclarar</h3><p>Una prueba de 20–25 minutos puede alternar preguntas del curso, prerrequisitos y una tarea de transferencia. Conviene pedir pasos y anotar el lugar donde se detiene el procedimiento.</p></div><div><h3>Entrenar y revisar</h3><p>Explicar primero, hacer juntos después, dejar un intento autónomo y terminar con una aplicación. La consolidación requiere volver en días distintos; el portal proporciona una ayuda, no una certificación.</p></div></div><p><a href="./materiales/04_Diagnostico_Fracciones_D1.pdf" target="_blank" rel="noopener noreferrer">Abrir prueba diagnóstica D1 de fracciones (PDF) →</a></p><div class="note">El documento «MAER · Capa 2, versión 0.1» recibido con el proyecto indica expresamente que se trata de una propuesta pendiente de validación. Esta web no modifica ni aprueba ese texto canónico.</div></section><section class="panel" style="margin-top:22px"><h2>Arquitectura para próximas entregas</h2><p>Los módulos se almacenan como contenido estructurado en <code>data/catalog.json</code>; la función Python <code>tools/generar_catalogo.py</code> regenera la versión JavaScript. Cada tema tiene identificador estable, cursos aplicables, prerrequisitos fuertes y débiles, pasos, ejemplos, error frecuente y generador de ejercicios.</p><a class="btn" href="./docs/GUIA_DE_AMPLIACION.md" target="_blank">Guía de ampliación y control de calidad</a></section>`}
function notFound(){return `${breadcrumbs([['Página no encontrada']])}<section class="empty"><h2>Esta ruta todavía no está disponible.</h2><p>El portal sigue creciendo. Puedes volver al índice y elegir un tema publicado.</p><a class="btn primary" href="#/catalogo">Ver temario</a></section>`}
function getRoute(){const hash=(location.hash||'#/inicio').slice(2),path=hash.split('?')[0].split('/');return {page:path[0]||'inicio',args:path.slice(1)}}
function render(){const {page,args}=getRoute();setNav(page);if(page==='inicio')APP.innerHTML=home();else if(page==='catalogo'){APP.innerHTML=catalog();updateCatalog()}else if(page==='tema')APP.innerHTML=topic(args[0]);else if(page==='practica')APP.innerHTML=quiz();else if(page==='maer')APP.innerHTML=maer();else if(page==='diagnostico')APP.innerHTML=diagnostic();else if(page==='progreso')APP.innerHTML=summary();else if(page==='docentes')APP.innerHTML=docentes();else APP.innerHTML=notFound();document.title=(page==='tema'&&lookup[args[0]]?`${lookup[args[0]].title} | `:page==='catalogo'?'Temario | ':'')+'Matemáticas · Academia Teseracto'}
function updateVisual(){const t=lookup[getRoute().args[0]]?.visual;if(!t)return;if(t==='fraction-line'&&ui.viz.n>2*ui.viz.d)ui.viz.n=2*ui.viz.d;if((t==='fractions'||t==='fraction-ops')&&ui.viz.n>ui.viz.d)ui.viz.n=ui.viz.d;document.querySelectorAll('[data-vkey]').forEach(el=>{if(el.dataset.vkey==='n')el.value=ui.viz.n});const graph=renderVisual(t);if($('svgwrap'))$('svgwrap').innerHTML=graph.svg;if($('vcap'))$('vcap').textContent=graph.caption;document.querySelectorAll('.v-val').forEach(x=>x.textContent=ui.viz[x.dataset.value])}
function checkQuiz(){const s=ui.quiz;if(!s||s.checked)return;const ans=$('quiz-answer')?.value.trim();if(!ans){notify('Escribe tu respuesta antes de comprobar');return}s.answer=ans;s.checked=true;s.results.push(P.correct(s.items[s.index],ans));render()}
function nextQuiz(){const s=ui.quiz;if(!s?.checked)return;s.index++;s.checked=false;s.answer='';if(s.index>=s.items.length)markQuizFinished();render()}
function nextDiagnostic(){const s=ui.diagnostic;if(!s||s.index>=12)return;const reply=$('diag-answer')?.value.trim()||'';const ex=s.items[s.index];s.answers.push({id:ex.id,right:P.correct(ex,reply),reply:reply||null});s.index++;if(s.index===12){s.finished=true;storage.diagnostics.push({grade:s.grade,when:now(),results:s.answers.map(a=>({id:a.id,right:a.right}))});persist()}render()}
function exportJSON(){const payload={format:'teseracto-matematicas-progreso',version:1,exported:now(),data:storage};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`teseracto-matematicas-progreso-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);notify('Archivo JSON preparado')}
function importJSON(file){if(!file)return;if(file.size>3_000_000){notify('El archivo es demasiado grande');return}const rd=new FileReader();rd.onload=()=>{try{const obj=JSON.parse(String(rd.result)),src=obj.format==='teseracto-matematicas-progreso'?obj.data:obj;if(!src||!Array.isArray(src.records)||!Array.isArray(src.bookmarks))throw Error('Formato desconocido');const records=src.records.filter(r=>lookup[r.id]&&['guided','independent','transfer'].includes(r.mode)&&Number.isInteger(r.score)&&r.score>=0&&r.score<=5&&r.total===5&&Number.isFinite(Date.parse(r.when))).slice(-20000);const maps=new Set(storage.records.map(r=>[r.id,r.when,r.mode,r.score].join(':')));for(const r of records){const key=[r.id,r.when,r.mode,r.score].join(':');if(!maps.has(key)){storage.records.push({id:r.id,mode:r.mode,score:r.score,total:5,when:r.when});maps.add(key)}}storage.bookmarks=[...new Set([...storage.bookmarks,...src.bookmarks.filter(id=>lookup[id])])];storage.touched=[...new Set([...storage.touched,...(Array.isArray(src.touched)?src.touched:[]).filter(id=>lookup[id])])];persist();render();notify(`Progreso importado: ${records.length} registros válidos`)}catch(e){notify('No se pudo importar: JSON no compatible')}};rd.readAsText(file)}
function delegatedClick(e){const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action,id=el.dataset.id,mode=el.dataset.mode;
if(act==='start-quiz')quizStart(id,mode);
else if(act==='quiz-check')checkQuiz();else if(act==='quiz-next')nextQuiz();else if(act==='quiz-hint'){const node=$('quiz-hint');if(node)node.style.display=node.style.display==='none'?'block':'none'}
else if(act==='bookmark'){storage.bookmarks=storage.bookmarks.includes(id)?storage.bookmarks.filter(x=>x!==id):[...storage.bookmarks,id];persist();render();notify(storage.bookmarks.includes(id)?'Tema guardado':'Tema retirado de guardados')}
else if(act==='reset-filters'||act==='expand-search'){ui.stage='all';ui.grade='all';ui.group='all';ui.area='all';if(act==='reset-filters')ui.search='';history.replaceState(null,'','#/catalogo');render()}
else if(act==='print')window.print();
else if(act==='start-diagnostic')diagnosticStart();else if(act==='diag-next')nextDiagnostic();
else if(act==='export-json')exportJSON();else if(act==='import-json')$('import-file').click();
else if(act==='clear-progress'){if(window.confirm('¿Quieres borrar de este navegador el historial, los temas guardados y las exploraciones? Esta acción no se puede deshacer sin una copia JSON.')){storage={version:1,records:[],bookmarks:[],diagnostics:[],touched:[]};persist();render();notify('Progreso local borrado')}}
}
document.addEventListener('click',delegatedClick);
document.addEventListener('submit',e=>{if(e.target.id==='home-search-form'){e.preventDefault();const q=$('home-search').value.trim();location.hash='#/catalogo?q='+encodeURIComponent(q)}});
$('skip-content')?.addEventListener('click',()=>APP.focus());
document.addEventListener('input',e=>{if(e.target.id==='find-topic'){ui.search=e.target.value;updateCatalog()}if(e.target.hasAttribute('data-vkey')){const key=e.target.dataset.vkey;ui.viz[key]=Number(e.target.value);updateVisual()}if(e.target.id==='quiz-answer'&&ui.quiz&&!ui.quiz.checked)ui.quiz.answer=e.target.value});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='stage-filter'){ui.stage=el.value;ui.grade='all';ui.area='all';ui.group='all';history.replaceState(null,'',catalogHref());const grade=$('grade-filter');if(grade)grade.outerHTML=`<select class="select" id="grade-filter"><option value="all">Todos los cursos</option>${Object.entries(C.courses).filter(([g])=>ui.stage==='all'||stageOf(g)===ui.stage).map(([g,n])=>`<option value="${g}">${n}</option>`).join('')}</select>`;const area=$('group-filter');if(area)area.value='all';updateCatalog()}else if(el.id==='grade-filter'){ui.grade=el.value;history.replaceState(null,'',catalogHref());updateCatalog()}else if(el.id==='group-filter'){ui.group=el.value;updateCatalog()}else if(el.id==='diag-grade'){ui.diagGrade=el.value}else if(el.id==='import-file'){importJSON(el.files[0]);el.value=''}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='quiz-answer'&&!ui.quiz?.checked){e.preventDefault();checkQuiz()}if(e.key==='Enter'&&e.target.id==='diag-answer'){e.preventDefault();nextDiagnostic()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
if(!location.hash)location.hash='#/inicio';render();
})();
